mapper.select:

SELECT A.ORD_NM AS ordNm /* 추후 상세 데이터 구현 */,
       TO_CHAR(A.FSR_DTM, 'YYYY-MM-DD HH:mm:SS') AS fsrDtm,
       NULL AS fmtInfo /* 추후 수행사인 정보 구현 */,
       *
FROM ODS.S_MOOORPTD A
WHERE A.PT_NO = #{ptNo}
  AND A.MED_PACT_TP_CD = #{medPactTpCd}
  AND A.ORD_DT::DATE = #{ordDt}::DATE
  AND A.ODAPL_POP_CD = #{odaplPopCd}
  AND A.FSR_STF_NO = #{fsrStfNo}
  AND A.ORD_CTG_CD NOT IN ('TRM')
ORDER BY A.ODAPL_POP_CD, FSR_STF_NO, SCRN_SORT_SEQ
